def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_op = op[-1]
    opp_def = op.count('D')
    my_def = my.count('D')

    if n == 99:
        return 'D'

    # Probe for AllC exploitation
    if opp_def == 0:
        if n < 15:
            return 'C'
        elif n == 15:
            return 'D'
        elif n == 16:
            return 'C'
        else:
            if op[16] == 'C':
                return 'D'

    # Trust mode: opponent cooperated for the first 10 rounds
    trust = (n >= 10 and all(a == 'C' for a in op[:10]))
    if trust:
        # Pattern detection for periodic strategies
        if n >= 10:
            for p in range(2, 7):
                if n >= 2*p and op[-p:] == op[-2*p:-p] and 'D' in op[-p:]:
                    return 'D'
        if opp_def > 6:
            return 'D'
        else:
            return 'C'

    # Base retaliatory logic
    opp_def_rate = opp_def / n

    opp_d_streak = 0
    for a in reversed(op):
        if a == 'D':
            opp_d_streak += 1
        else:
            break
    my_d_streak = 0
    for a in reversed(my):
        if a == 'D':
            my_d_streak += 1
        else:
            break
    if opp_d_streak >= 3 and my_d_streak >= 2:
        return 'C'

    if last_op == 'D':
        if opp_def_rate > 0.4 or opp_d_streak >= 2:
            return 'D'
        else:
            return 'C'
    else:
        if opp_def_rate > 0.6 and n > 20:
            return 'D'
        return 'C'
